-- surface: tonumber with a base skips a leading '+' (lbaselib.c b_str2int); a hex float numeral is strtod's, correctly rounded, however many digits it has (luaconf.h lua_strx2number); a bitwise operand with no integer value is named (ldebug.c luaG_tointerror varinfo)
print(tonumber("+10", 2), tonumber(" -ff ", 16), tonumber("1 0", 2), tonumber("+", 10), tonumber("\v7\f", 8), tonumber("zz", 36), tonumber("8", 8))
print(tonumber("0x3." .. string.rep("0", 1000)) == 3, tonumber("0x." .. string.rep("0", 300) .. "1p1200") == 0.0625)
print(0x3. == 3)
print(string.format("%a %a %a", tonumber("0x1.00000000000008p0"), tonumber("0x1.000000000000081p0"), 0x1.00000000000018p0))
print(pcall(load("local a = 2.5 return a << 1")))
print(pcall(load("local a = 2 local b = 2.5 return a | b")))
print(pcall(load("local s = 1.5 return ~s")))
print(pcall(load("x = 3.5 return x >> 1")))
